import { withProjectLine } from "../../core/projects.js";
/** The project line when one applies, then each rule under its ref. */
export function formatRulesText(result) {
    const body = result.rules.length === 0
        ? "No rules apply here."
        : result.rules.map((rule) => `## ${rule.ref}\n\n${rule.content}`).join("\n\n");
    return withProjectLine(body, result.project);
}
export const rulesFormatters = [
    { command: "rules", handler: (r) => formatRulesText(r) },
];
